@dataclass(frozen=True)
class ConstructorRoute:
    name: str
    priority: int
    constructor_family: str
    variant_name: str
    recommended_action: str
    authority_level: str = "CONSTRUCTOR_SCHEMA_EMPIRICAL"


def promoted_constructor_routes() -> List[ConstructorRoute]:
    routes: List[ConstructorRoute] = []
    for c in PROMOTED_CONSTRUCTOR_CATALOG:
        routes.append(ConstructorRoute(
            name=str(c.get("catalog_id", c.get("constructor_family", ""))),
            priority=int(c.get("priority", 999)),
            constructor_family=str(c.get("constructor_family", "")),
            variant_name=str(c.get("variant_name", "")),
            recommended_action=str(c.get("recommended_action", "")),
            authority_level=str(c.get("authority_level", "CONSTRUCTOR_SCHEMA_EMPIRICAL")),
        ))
    return sorted(routes, key=lambda r: (r.priority, r.constructor_family, r.variant_name))


def choose_constructor_for_error(error_class: str, source_skeleton: str = "", target_skeleton: str = "") -> List[ConstructorRoute]:
    error_class = str(error_class or "").upper()
    routes = promoted_constructor_routes()

    if error_class in {"LEAN_ERROR", "HEADER_ERROR", "UNKNOWN_UNIVERSE", "UNKNOWN_IDENTIFIER"}:
        return [r for r in routes if r.constructor_family == "FIXED_HEADER_EXACT_REPLAY"] + routes

    if error_class in {"UNSOLVED_GOALS", "RW_FAILURE", "REWRITE_FAILED"}:
        preferred = [
            r for r in routes
            if r.constructor_family in {
                "FAST_WITNESS_COMPLETED_ONE_BRIDGE",
                "EXPLICIT_SUBPOSITION_CONGRARG_BRIDGE_REPAIR",
            }
        ]
        return preferred + [r for r in routes if r not in preferred]

    if error_class in {"TYPE_MISMATCH"}:
        preferred = [
            r for r in routes
            if r.constructor_family == "EXPLICIT_SUBPOSITION_CONGRARG_BRIDGE_REPAIR"
        ]
        return preferred + [r for r in routes if r not in preferred]

    return routes


def mandatory_lean_header() -> str:
    return '''universe u

class Magma (M : Type u) where
  op : M -> M -> M

infixl:70 " ◇ " => Magma.op
'''


